const timeline=document.querySelector('#timeline');
chapters.forEach((c,i)=>{const b=document.createElement('button');b.type='button';b.role='tab';b.dataset.index=i;b.setAttribute('aria-selected',i===0?'true':'false');b.innerHTML=`<small>${c.kind} · ${c.time}</small><strong>${c.name}</strong>`;timeline.appendChild(b)});
const stage=document.querySelector('#timeStage');
function showChapter(index){const c=chapters[index];document.querySelectorAll('#timeline button').forEach((b,i)=>b.setAttribute('aria-selected',i===index?'true':'false'));document.querySelector('#chapterLabel').textContent=`CAPÍTULO ${String(index+1).padStart(2,'0')} / ${chapters.length}`;document.querySelector('#eraTime').textContent=c.time;document.querySelector('#eraName').textContent=c.name;document.querySelector('#eraTagline').textContent=c.tag;document.querySelector('#factTitle').textContent=c.fact;document.querySelector('#factDetail').textContent=c.detail;stage.style.setProperty('--sky1',c.colors[0]);stage.style.setProperty('--sky2',c.colors[1]);stage.style.setProperty('--ground',c.colors[2]);stage.style.setProperty('--landback',c.colors[3]);stage.style.setProperty('--landfront',c.colors[4]);stage.style.setProperty('--sun',c.colors[5]);stage.style.setProperty('--shape',c.shape);document.querySelector('#factCard').setAttribute('aria-expanded','false')}
timeline.addEventListener('click',e=>{const b=e.target.closest('button');if(b){showChapter(Number(b.dataset.index));b.scrollIntoView({behavior:'smooth',block:'nearest',inline:'center'})}});
timeline.addEventListener('keydown',e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();const current=[...timeline.children].indexOf(document.activeElement);let next=e.key==='Home'?0:e.key==='End'?chapters.length-1:Math.max(0,Math.min(chapters.length-1,current+(e.key==='ArrowRight'?1:-1)));timeline.children[next].focus();timeline.children[next].click()});
document.querySelector('#factCard').addEventListener('click',e=>{const b=e.currentTarget;b.setAttribute('aria-expanded',b.getAttribute('aria-expanded')!=='true')});

const specimens=[
  {name:'Estromatolito',period:'ARCAICO',age:'3,500 Ma',group:'Comunidad microbiana',habitat:'Costas someras',zone:'ocean',mark:'ST',description:'Estructuras construidas capa por capa por comunidades de microbios. No son un solo organismo: son ecosistemas y algunos de los rastros de vida más antiguos.'},
  {name:'Dickinsonia',period:'EDIACÁRICO',age:'558 Ma',group:'Animal temprano',habitat:'Fondo marino',zone:'ocean',mark:'DI',description:'Un cuerpo ovalado y segmentado sin boca visible. Su parentesco exacto fue misterioso durante décadas; evidencias químicas apoyan que era un animal.'},
  {name:'Anomalocaris',period:'CÁMBRICO',age:'508 Ma',group:'Artrópodo troncal',habitat:'Océano abierto',zone:'ocean',mark:'AN',description:'Nadador con ojos compuestos, apéndices frontales y una boca circular. Fue uno de los grandes depredadores de los mares cámbricos.'},
  {name:'Eurypterus',period:'SILÚRICO',age:'420 Ma',group:'Quelicerado',habitat:'Lagunas costeras',zone:'ocean',mark:'EU',description:'Uno de los llamados escorpiones marinos. Sus parientes más cercanos entre los animales actuales incluyen arañas, escorpiones y cangrejos herradura.'},
  {name:'Tiktaalik',period:'DEVÓNICO',age:'375 Ma',group:'Tetrapodomorfo',habitat:'Aguas poco profundas',zone:'ocean',mark:'TI',description:'Combinaba escamas y aletas con cuello móvil, costillas robustas y huesos semejantes a una muñeca: un mosaico entre peces y vertebrados terrestres.'},
  {name:'Meganeura',period:'CARBONÍFERO',age:'305 Ma',group:'Insecto griffinfly',habitat:'Bosque pantanoso',zone:'air',mark:'ME',description:'Insecto volador emparentado con las libélulas, con una envergadura cercana a 65 centímetros. Vivió en bosques húmedos ricos en oxígeno.'},
  {name:'Dimetrodon',period:'PÉRMICO',age:'290 Ma',group:'Sinápsido',habitat:'Llanuras cálidas',zone:'land',mark:'DM',description:'No era dinosaurio: pertenecía a la rama evolutiva que también incluye a los mamíferos. Su gran vela probablemente cumplía más de una función.'},
  {name:'Lystrosaurus',period:'TRIÁSICO',age:'250 Ma',group:'Dicinodonto',habitat:'Llanuras interiores',zone:'land',mark:'LY',description:'Herbívoro de pico córneo que sobrevivió a la mayor extinción conocida. Durante un tiempo fue extraordinariamente abundante en varios continentes.'},
  {name:'Stegosaurus',period:'JURÁSICO',age:'150 Ma',group:'Dinosaurio ornitisquio',habitat:'Planicies y bosques',zone:'land',mark:'SG',description:'Sus placas no formaban una armadura continua y estaban recorridas por vasos sanguíneos. La cola con púas sí era una defensa formidable.'},
  {name:'Argentinosaurus',period:'CRETÁCICO',age:'95 Ma',group:'Dinosaurio saurópodo',habitat:'Planicies de Patagonia',zone:'land',mark:'AR',description:'Uno de los animales terrestres más grandes conocidos. Sus dimensiones se estiman a partir de fósiles incompletos, por lo que existe un rango y no una cifra exacta.'},
  {name:'Basilosaurus',period:'PALEÓGENO',age:'40 Ma',group:'Cetáceo temprano',habitat:'Mares cálidos',zone:'ocean',mark:'BA',description:'A pesar de su nombre, era una ballena. Tenía un cuerpo extremadamente alargado y pequeñas patas traseras que ya no servían para caminar.'},
  {name:'Smilodon',period:'CUATERNARIO',age:'20,000 años',group:'Felino macairodontino',habitat:'Mosaicos abiertos',zone:'land',mark:'SM',description:'Felino robusto de caninos largos. No era un tigre y probablemente cazaba mediante emboscadas, sujetando a presas grandes con potentes extremidades delanteras.'}
];
const archiveGrid=document.querySelector('#archiveGrid'),searchInput=document.querySelector('#archiveSearch'),dialog=document.querySelector('#specimenDialog');let activeFilter='all';
function renderArchive(){const query=searchInput.value.trim().toLocaleLowerCase('es');const visible=specimens.filter(s=>(activeFilter==='all'||s.zone===activeFilter)&&`${s.name} ${s.period} ${s.group}`.toLocaleLowerCase('es').includes(query));archiveGrid.innerHTML=visible.map(s=>`<button class="specimen-card" type="button" data-name="${s.name}"><span class="specimen-number">${String(specimens.indexOf(s)+1).padStart(2,'0')}</span><span class="specimen-mark" aria-hidden="true">${s.mark}</span><span class="specimen-period">${s.period} · ${s.age}</span><strong>${s.name}</strong><small>${s.group}</small><i>Explorar →</i></button>`).join('');document.querySelector('#archiveEmpty').hidden=visible.length>0}
document.querySelector('.archive-filters').addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;activeFilter=b.dataset.filter;document.querySelectorAll('.archive-filters button').forEach(x=>x.classList.toggle('active',x===b));renderArchive()});
searchInput.addEventListener('input',renderArchive);
archiveGrid.addEventListener('click',e=>{const card=e.target.closest('.specimen-card');if(!card)return;const s=specimens.find(x=>x.name===card.dataset.name);document.querySelector('#dialogPeriod').textContent=s.period;document.querySelector('#dialogMark').textContent=s.mark;document.querySelector('#dialogName').textContent=s.name;document.querySelector('#dialogGroup').textContent=s.group;document.querySelector('#dialogDescription').textContent=s.description;document.querySelector('#dialogAge').textContent=s.age;document.querySelector('#dialogHabitat').textContent=s.habitat;dialog.showModal()});
document.querySelector('#dialogClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});

const clueText=['La marca tiene tres dedos largos y termina en garras. Es la huella de un terópodo bípedo.','La distancia entre huellas indica una marcha tranquila, no una persecución. El animal mediría varios metros.','Las marcas terminan en una antigua orilla. Quizá buscaba agua o seguía a otra criatura.'];
document.querySelectorAll('.clue').forEach(b=>b.addEventListener('click',()=>{document.querySelectorAll('.clue').forEach(x=>x.classList.remove('active'));b.classList.add('active');document.querySelector('#clueReader').textContent=clueText[Number(b.dataset.clue)]}));
document.querySelector('#checkAnswer').addEventListener('click',()=>{const selected=document.querySelector('input[name=answer]:checked');const result=document.querySelector('#result');if(!selected){result.className='result wrong';result.textContent='Elige una hipótesis antes de comprobarla.';return}const ok=selected.value==='theropod';result.className=`result ${ok?'correct':'wrong'}`;result.textContent=ok?'La evidencia coincide. La forma tridáctila y la zancada corresponden a un terópodo mediano. Aún no podemos conocer la especie exacta.':'Esa hipótesis no explica la forma tridáctila. Revisa la huella: la anatomía importa más que el tamaño.'});

document.querySelectorAll('.pulse-chart button').forEach(b=>{const show=()=>document.querySelector('#chartTooltip').textContent=b.dataset.label;b.addEventListener('mouseenter',show);b.addEventListener('focus',show)});

let audioContext,oscillator,gain;
document.querySelector('#soundToggle').addEventListener('click',async e=>{const btn=e.currentTarget;const on=btn.getAttribute('aria-pressed')==='true';if(on){gain?.gain.exponentialRampToValueAtTime(.0001,audioContext.currentTime+.4);setTimeout(()=>audioContext?.close(),500);btn.setAttribute('aria-pressed','false');return}audioContext=new AudioContext();oscillator=audioContext.createOscillator();gain=audioContext.createGain();oscillator.type='sine';oscillator.frequency.value=82;gain.gain.value=.0001;oscillator.connect(gain).connect(audioContext.destination);oscillator.start();gain.gain.exponentialRampToValueAtTime(.018,audioContext.currentTime+1);btn.setAttribute('aria-pressed','true')});

showChapter(0);
renderArchive();
